SELECT p.gender, a.admission_type, s.stay_length, COUNT(DISTINCT i.itemid) AS num_exams, AVG(i.value) AS avg_exam_duration, MIN(i.value) AS min_exam_duration, MAX(i.value) AS max_exam_duration FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN stay s ON a.stay_id = s.stay_id JOIN chartevents e ON a.subject_id = e.subject_id AND a.hadm_id = e.hadm_id JOIN inputevents i ON a.subject_id = i.subject_id AND a.hadm_id = i.hadm_id AND i.starttime = e.charttime AND i.endtime = e.storetime WHERE p.gender = 'F' AND p.anchor_age >= 78 AND p.anchor_year_group IN ('MULTI-TRAUMA') AND s.stay_length BETWEEN 1 AND 7 AND e.itemid IN (SELECT itemid FROM d_items WHERE category = 'Exam') GROUP BY p.gender, a.admission_type, s.stay_length ORDER BY p.gender, a.admission_type, s.stay_length NULLS LAST;